import React, { useEffect } from "react";

const Child = ({ data }) => {
  useEffect(() => {
    console.log("Child component updated");
  }, [data]);
  return (
    <div>
      <h1>Child</h1>
      {data.map((item) => (
        <p key={item}>{item}</p>
      ))}
    </div>
  );
};

export default Child;
